// Classificação protegida: produtos da linha Sophie/Toy Story são itens de beleza, não brinquedos.
window.DACALI_PRODUCTS = window.DACALI_PRODUCTS.map(product => {
  const key = `${product.name || ""} ${product.title || ""}`.toLowerCase();
  if (key.includes("sophie") && key.includes("toy story")) {
    return { ...product, category: "beleza", label: "BELEZA" };
  }
  return product;
});
